<div class="row g-3"><div class="col-md-6"><label class="form-label">Tên sản phẩm</label><input name="name" class="form-control" value="{{ old('name',$product->name) }}" required></div><div class="col-md-6"><label class="form-label">Slug</label><input name="slug" class="form-control" value="{{ old('slug',$product->slug) }}" required></div><div class="col-md-6"><label class="form-label">Danh mục</label><select name="category_id" class="form-select" required>@foreach($categories as $category)<option value="{{ $category->id }}" @selected(old('category_id',$product->category_id)==$category->id)>{{ $category->name }}</option>@endforeach</select></div><div class="col-md-6"><label class="form-label">Thương hiệu</label><select name="brand_id" class="form-select" required>@foreach($brands as $brand)<option value="{{ $brand->id }}" @selected(old('brand_id',$product->brand_id)==$brand->id)>{{ $brand->name }}</option>@endforeach</select></div><div class="col-12"><label class="form-label">Giới thiệu sản phẩm</label><textarea name="description" class="form-control" rows="6" maxlength="10000">{{ old('description',$product->description) }}</textarea><small class="text-muted">Văn bản thuần túy, xuống dòng được giữ nguyên.</small></div></div>
<hr><h3 class="h5">THÔNG SỐ KỸ THUẬT</h3><div id="spec-groups">@foreach($specs as $gi=>$group)<div class="spec-group border rounded p-3 mb-3"><div class="d-flex gap-2"><input name="specifications[{{$gi}}][group]" class="form-control" placeholder="Tên nhóm" value="{{ $group['group'] ?? '' }}" maxlength="100" required><button type="button" class="btn btn-outline-danger remove-group">Xóa nhóm</button></div><div class="spec-rows mt-2">@foreach(($group['rows']??[]) as $ri=>$row)<div class="row g-2 mb-2 spec-row"><div class="col-md-5"><input name="specifications[{{$gi}}][rows][{{$ri}}][name]" class="form-control" placeholder="Tên thông số" value="{{ $row['name']??'' }}" maxlength="100" required></div><div class="col-md-6"><input name="specifications[{{$gi}}][rows][{{$ri}}][value]" class="form-control" placeholder="Giá trị" value="{{ $row['value']??'' }}" maxlength="500" required></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove-row">×</button></div></div>@endforeach</div><button type="button" class="btn btn-sm btn-outline-secondary add-row">+ Thêm thông số</button></div>@endforeach</div><button type="button" id="add-group" class="btn btn-outline-primary">+ Thêm nhóm</button><div class="form-check mt-3"><input type="checkbox" name="is_active" value="1" class="form-check-input" id="active" @checked(old('is_active',$product->exists?$product->is_active:true))><label for="active" class="form-check-label">Đang kinh doanh</label></div><button class="btn btn-danger mt-3">Lưu sản phẩm</button></form>
<script>document.addEventListener('DOMContentLoaded',()=>{const box=document.querySelector('#spec-groups');const renumber=()=>box.querySelectorAll('.spec-group').forEach((g,i)=>{g.querySelector('input').name=`specifications[${i}][group]`;g.querySelectorAll('.spec-row').forEach((r,j)=>{r.querySelectorAll('input').forEach((x,k)=>x.name=`specifications[${i}][rows][${j}][${k?'value':'name'}]`);});});const row=()=>{const d=document.createElement('div');d.className='row g-2 mb-2 spec-row';d.innerHTML='<div class="col-md-5"><input class="form-control" placeholder="Tên thông số" maxlength="100" required></div><div class="col-md-6"><input class="form-control" placeholder="Giá trị" maxlength="500" required></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove-row">×</button></div>';return d};box.addEventListener('click',e=>{if(e.target.matches('.remove-row'))e.target.closest('.spec-row').remove();if(e.target.matches('.remove-group'))e.target.closest('.spec-group').remove();if(e.target.matches('.add-row'))e.target.previousElementSibling.append(row());renumber()});document.querySelector('#add-group').onclick=()=>{const g=document.createElement('div');g.className='spec-group border rounded p-3 mb-3';g.innerHTML='<div class="d-flex gap-2"><input class="form-control" placeholder="Tên nhóm" maxlength="100" required><button type="button" class="btn btn-outline-danger remove-group">Xóa nhóm</button></div><div class="spec-rows mt-2"></div><button type="button" class="btn btn-sm btn-outline-secondary add-row">+ Thêm thông số</button>';box.append(g);g.querySelector('.add-row').click();renumber()};document.querySelector('#product-form').onsubmit=renumber});</script>